import pytest

DEFAULT_MODE = "fast"
DEFAULT_LEVEL = "3"


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay the given settings on the defaults mode=fast and level=3.

    keys[i] is set to values[i]. If a key repeats, the last value wins.
    Returns the resulting values: first mode, then level, then the values of
    any other keys in the order each key first appeared in `keys`.
    Pure computation: no I/O, environment access, or other side effects.

    Raises ValueError if keys and values have different lengths.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values must have the same length")
    merged: dict[str, str] = {"mode": DEFAULT_MODE, "level": DEFAULT_LEVEL}
    for k, v in zip(keys, values, strict=True):
        merged[k] = v
    return list(merged.values())


def test_defaults_only() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_level() -> None:
    assert settings(["level"], ["9"]) == ["fast", "9"]


def test_override_both_in_reverse_order() -> None:
    assert settings(["level", "mode"], ["1", "safe"]) == ["safe", "1"]


def test_extra_keys_in_given_order() -> None:
    assert settings(["z", "a", "m"], ["1", "2", "3"]) == ["fast", "3", "1", "2", "3"]


def test_extras_mixed_with_known_keys() -> None:
    assert settings(["x", "mode", "y"], ["1", "slow", "2"]) == ["slow", "3", "1", "2"]


def test_duplicate_extra_key_last_wins_first_position() -> None:
    assert settings(["a", "b", "a"], ["1", "2", "3"]) == ["fast", "3", "3", "2"]


def test_duplicate_known_key_last_wins() -> None:
    assert settings(["mode", "mode"], ["a", "b"]) == ["b", "3"]


def test_empty_string_values_preserved() -> None:
    assert settings(["mode", "k"], ["", ""]) == ["", "3", ""]


def test_length_mismatch_raises() -> None:
    with pytest.raises(ValueError):
        settings(["a", "b"], ["1"])
    with pytest.raises(ValueError):
        settings(["a"], ["1", "2"])


def test_inputs_not_mutated() -> None:
    keys = ["a", "mode"]
    values = ["1", "slow"]
    settings(keys, values)
    assert keys == ["a", "mode"]
    assert values == ["1", "slow"]
